import React from 'react';
import { HashRouter, Routes, Route } from 'react-router-dom';
import Home from './Home';

function App() {
  return (
    <HashRouter>
      <Routes>
        <Route path="/" element={<Home lang="pt" />} />
        <Route path="/en" element={<Home lang="en" />} />
      </Routes>
    </HashRouter>
  );
}

export default App;
